const pptxgen = require('pptxgenjs');

const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.author = 'Gemini CLI';
pres.title = 'State of the Web 2020-2025';

const theme = {
  primary: "03045e",
  secondary: "0077b6",
  accent: "00b4d8",
  light: "90e0ef",
  bg: "f7f9fc"
};

function addBadge(slide, num) {
  const pageStr = String(num).padStart(2, '0');
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fill: { color: theme.accent },
    rectRadius: 0.15
  });
  slide.addText(pageStr, {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle", margin: 0
  });
}

function addSlideTitle(slide, title) {
  slide.addText(title, {
    x: 0.5, y: 0.4, w: 9, h: 0.8,
    fontSize: 28, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left", valign: "middle"
  });
  slide.addShape(pres.shapes.LINE, {
    x: 0.5, y: 1.2, w: 9, h: 0,
    line: { color: theme.accent, width: 2 }
  });
}

function slide1() {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 3.5, w: 10, h: 2.125,
    fill: { color: theme.secondary }
  });

  slide.addText("State of the Web 2020–2025", {
    x: 0.5, y: 1.5, w: 9, h: 1,
    fontSize: 48, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "left"
  });

  slide.addText("Tracking Page Weight, Protocols & Security at Scale", {
    x: 0.5, y: 2.5, w: 9, h: 0.6,
    fontSize: 24, fontFace: "Arial",
    color: theme.light, align: "left"
  });

  slide.addText("Based on HTTP Archive crawl data (Jan 2020 – Mar 2026)\nAudience: Web Performance Engineers & Front-end Architects", {
    x: 0.5, y: 4.0, w: 9, h: 1,
    fontSize: 16, fontFace: "Arial",
    color: "FFFFFF", align: "left", breakLine: true
  });
}

function slide2() {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };
  addSlideTitle(slide, "Crawl Sample Size Tripled: From ~5M to 16M Desktop URLs Since 2020");
  addBadge(slide, 2);

  const chartData = [
    {
      name: "Desktop URLs (Millions)",
      labels: ["Jan 2020", "Mid 2021", "Mid 2022", "Mid 2023", "Mid 2024", "Jan 2026"],
      values: [5, 8, 15, 16, 16, 16]
    },
    {
      name: "Mobile URLs (Millions)",
      labels: ["Jan 2020", "Mid 2021", "Mid 2022", "Mid 2023", "Mid 2024", "Jan 2026"],
      values: [3.5, 6, 10, 12.5, 12.5, 12.5]
    }
  ];

  slide.addChart(pres.charts.LINE, chartData, {
    x: 0.5, y: 1.5, w: 9, h: 3.5,
    chartColors: [theme.primary, theme.accent],
    lineSize: 4, lineSmooth: true,
    showLegend: true, legendPos: "b",
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true, dataLabelPosition: "t", dataLabelColor: theme.primary,
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true }
  });
}

function slide3() {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };
  addSlideTitle(slide, "Median Page Weight Climbs Steadily to ~2,000 KB on Desktop");
  addBadge(slide, 3);

  const chartData = [
    {
      name: "Desktop (KB)",
      labels: ["2020", "2021", "2022", "2023", "2024", "2025", "2026"],
      values: [1600, 1670, 1740, 1800, 1860, 1930, 2000]
    },
    {
      name: "Mobile (KB)",
      labels: ["2020", "2021", "2022", "2023", "2024", "2025", "2026"],
      values: [1500, 1560, 1630, 1700, 1760, 1830, 1900]
    }
  ];

  slide.addChart(pres.charts.LINE, chartData, {
    x: 0.5, y: 1.5, w: 6.5, h: 3.5,
    chartColors: [theme.primary, theme.accent],
    lineSize: 4, lineSmooth: true,
    showLegend: true, legendPos: "b",
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true }
  });

  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 7.2, y: 2.0, w: 2.3, h: 2,
    fill: { color: theme.secondary }, rectRadius: 0.1
  });
  slide.addText([
    { text: "Up ~25%", options: { fontSize: 36, bold: true, color: "FFFFFF", breakLine: true } },
    { text: "Since 2020 on both Desktop and Mobile.\n\nThe 75th percentile desktop page now exceeds 4,000 KB.", options: { fontSize: 14, color: theme.light } }
  ], {
    x: 7.3, y: 2.1, w: 2.1, h: 1.8, align: "center", valign: "middle"
  });
}

function slide4() {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };
  addSlideTitle(slide, "76 Requests per Desktop Page While TCP Connections Drop to 12");
  addBadge(slide, 4);

  slide.addText("Median Total Requests", {
    x: 0.5, y: 1.5, w: 4, h: 0.5,
    fontSize: 20, fontFace: "Arial", color: theme.primary, bold: true
  });

  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 2.1, w: 1.9, h: 1.5,
    fill: { color: "FFFFFF" }, line: { color: theme.accent, width: 2 }, rectRadius: 0.1
  });
  slide.addText("Desktop\n76", {
    x: 0.5, y: 2.1, w: 1.9, h: 1.5, align: "center", valign: "middle",
    fontSize: 32, bold: true, color: theme.primary, breakLine: true
  });

  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 2.6, y: 2.1, w: 1.9, h: 1.5,
    fill: { color: "FFFFFF" }, line: { color: theme.accent, width: 2 }, rectRadius: 0.1
  });
  slide.addText("Mobile\n71", {
    x: 2.6, y: 2.1, w: 1.9, h: 1.5, align: "center", valign: "middle",
    fontSize: 32, bold: true, color: theme.primary, breakLine: true
  });

  slide.addText("Desktop up 2.7%, Mobile up 2.9%", {
    x: 0.5, y: 3.8, w: 4, h: 0.5, align: "center",
    fontSize: 16, color: theme.secondary, bold: true
  });

  slide.addText("Median TCP Connections / Page", {
    x: 5.0, y: 1.5, w: 4.5, h: 0.5,
    fontSize: 20, fontFace: "Arial", color: theme.primary, bold: true, align: "center"
  });

  const chartData = [
    { name: "Desktop (▼ 14.3%)", labels: ["2020", "2026"], values: [15, 12] },
    { name: "Mobile (▼ 26.7%)", labels: ["2020", "2026"], values: [15, 11] }
  ];

  slide.addChart(pres.charts.LINE, chartData, {
    x: 5.0, y: 2.1, w: 4.5, h: 2.5,
    chartColors: [theme.primary, theme.accent],
    lineSize: 4, lineSmooth: true,
    showLegend: true, legendPos: "b",
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true, dataLabelPosition: "t", dataLabelColor: theme.primary,
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true }
  });
}

function slide5() {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };
  addSlideTitle(slide, "HTTPS Requests Reach 99%: Encryption Is Now the Default");
  addBadge(slide, 5);

  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 1.8, w: 4.5, h: 2.5,
    fill: { color: theme.primary }, rectRadius: 0.2
  });
  slide.addText([
    { text: "99.2%", options: { fontSize: 64, bold: true, color: theme.accent, breakLine: true } },
    { text: "Desktop HTTPS Requests\n(Mobile closely follows at 99.1%)", options: { fontSize: 16, color: "FFFFFF" } }
  ], {
    x: 0.5, y: 1.8, w: 4.5, h: 2.5, align: "center", valign: "middle"
  });

  const chartData = [
    {
      name: "HTTPS Adoption %", labels: ["2020", "2021", "2022", "2023", "2024", "2025", "2026"],
      values: [80, 85, 90, 95, 97, 98, 99.2]
    }
  ];

  slide.addChart(pres.charts.LINE, chartData, {
    x: 5.3, y: 1.5, w: 4.2, h: 3,
    chartColors: [theme.secondary],
    lineSize: 5, lineSmooth: true,
    showLegend: false,
    valAxisMinVal: 70, valAxisMaxVal: 100,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
    showTitle: true, title: "Adoption Climb from ~80% to 99%", titleColor: theme.primary, titleFontSize: 16
  });
}

function slide6() {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };
  addSlideTitle(slide, "HTTP/2 Holds at ~58% While HTTP/3 Support Surges to 40%");
  addBadge(slide, 6);

  const chartData = [
    { name: "Desktop", labels: ["HTTP/2 Requests", "HTTP/3 Support"], values: [58.6, 38.7] },
    { name: "Mobile", labels: ["HTTP/2 Requests", "HTTP/3 Support"], values: [57.6, 40.0] }
  ];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.5, y: 1.5, w: 5.5, h: 3.5, barDir: "col",
    chartColors: [theme.secondary, theme.accent],
    showLegend: true, legendPos: "b",
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true, dataLabelPosition: "outEnd", dataLabelColor: theme.primary,
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true }
  });

  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 6.5, y: 1.8, w: 3.0, h: 2.5,
    fill: { color: "FFFFFF" }, line: { color: theme.light, width: 2 }, rectRadius: 0.1
  });
  slide.addText([
    { text: "Explosive Growth\n", options: { fontSize: 20, bold: true, color: theme.primary, breakLine: true } },
    { text: "HTTP/3 support has surged from near-zero in 2020.\n\n", options: { fontSize: 14, color: theme.secondary, breakLine: true } },
    { text: "Note: HTTP Archive measures HTTP/3 support rather than usage because fresh Chrome instances default to HTTP/2 on first connection.", options: { fontSize: 12, color: "64748B" } }
  ], {
    x: 6.7, y: 2.0, w: 2.6, h: 2.1, align: "left", valign: "top"
  });
}

function slide7() {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };
  addSlideTitle(slide, "Font-Display Usage Reaches 42% on Mobile, Up 61% Since 2020");
  addBadge(slide, 7);

  const chartData = [
    {
      name: "Adoption (%)",
      labels: ["Desktop (Up 14.9%)", "Mobile (Up 61.0%)"],
      values: [40.1, 42.5]
    }
  ];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.5, y: 1.5, w: 5.5, h: 3.5, barDir: "col",
    chartColors: [theme.secondary],
    showLegend: false,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true, dataLabelPosition: "outEnd", dataLabelColor: theme.primary,
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true }
  });

  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 6.5, y: 1.8, w: 3.0, h: 2,
    fill: { color: theme.accent }, rectRadius: 0.1
  });
  slide.addText([
    { text: "Avoiding FOIT\n", options: { fontSize: 20, bold: true, color: "FFFFFF", breakLine: true } },
    { text: "The font-display CSS property helps avoid the Flash of Invisible Text during web font loading.\n\nWhile adoption is growing strongly, >50% of pages still risk FOIT.", options: { fontSize: 14, color: theme.primary } }
  ], {
    x: 6.7, y: 2.0, w: 2.6, h: 1.6, align: "left", valign: "top"
  });
}

function slide8() {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  slide.addText("Key Takeaways: Bigger Pages, Smarter Protocols, Stronger Security", {
    x: 0.5, y: 0.4, w: 9, h: 0.8,
    fontSize: 24, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "left", valign: "middle"
  });

  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 1.4, w: 9, h: 3.6,
    fill: { color: "FFFFFF" }, rectRadius: 0.1
  });

  slide.addText([
    { text: "Page weight keeps climbing: ", options: { bold: true, fontSize: 16, bullet: true, color: theme.primary } },
    { text: "Median desktop pages transfer ~2,000 KB, roughly 25% heavier than in 2020.", options: { fontSize: 16, color: theme.secondary, breakLine: true } },
    { text: "\n" },

    { text: "HTTPS is the new baseline: ", options: { bold: true, fontSize: 16, bullet: true, color: theme.primary } },
    { text: "At 99%+ of requests, unencrypted HTTP is essentially extinct on the modern web.", options: { fontSize: 16, color: theme.secondary, breakLine: true } },
    { text: "\n" },

    { text: "HTTP/3 is the fastest-growing protocol metric: ", options: { bold: true, fontSize: 16, bullet: true, color: theme.primary } },
    { text: "From near-zero to ~40% support in under four years, HTTP/3 is rapidly becoming mainstream.", options: { fontSize: 16, color: theme.secondary, breakLine: true } },
    { text: "\n" },

    { text: "Fewer TCP connections despite more requests: ", options: { bold: true, fontSize: 16, bullet: true, color: theme.primary } },
    { text: "Multiplexing in HTTP/2 and HTTP/3 has cut median connections per page by 15–27%.", options: { fontSize: 16, color: theme.secondary, breakLine: true } },
    { text: "\n" },

    { text: "Font-display still underused: ", options: { bold: true, fontSize: 16, bullet: true, color: theme.primary } },
    { text: "At ~40–42% adoption, there is significant room for improvement in avoiding invisible text.", options: { fontSize: 16, color: theme.secondary } }
  ], {
    x: 0.8, y: 1.6, w: 8.4, h: 3.2, align: "left", valign: "middle"
  });

  addBadge(slide, 8);
}

slide1();
slide2();
slide3();
slide4();
slide5();
slide6();
slide7();
slide8();

pres.writeFile({ fileName: '/app/output/final_deck.pptx' })
  .then(fileName => {
    console.log(`Created file: ${fileName}`);
  })
  .catch(err => {
    console.error('Error generating presentation', err);
  });

